    "k003": "De zaak{{svg1}}",
    "k004": "<span class=\"nav__dd-kicker\">Wat Enki is</span> <a href=\"manifesto.html\"><b>Manifest</b><span>De brief — 86 verwijzingen</span></a> <a href=\"standard.html\"><b>Standaarden</b><span>De vier clausules die we eisen</span></a> <a href=\"manifesto.html#enki\"><b>Waarom Enki</b><span>De naam &amp; het argument</span></a>",
    "k005": "Het vakmanschap{{svg1}}",
    "k006": "<span class=\"nav__dd-kicker\">Wat wij leveren</span> <a href=\"device.html\"><b>Het apparaat</b><span>Open blauwdrukken voor een AI-datacenter op zakformaat</span></a> <a href=\"models.html\"><b>Modellen</b><span>Open gewichten, eerlijke kosten</span></a>",
    "k007": "Onderzoek",
